      pt: "O local da decisiva batalha de Yarmouk no ano 636, que marcou o fim do domínio bizantino na Síria.",
      fr: "Le lieu de la bataille décisive du Yarmouk en 636, qui marqua la fin de la domination byzantine en Syrie.",
